/// A 2D point with 64-bit integer coordinates (mirrors Clipper2's `Point64`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Point64 {
    pub x: i64,
    pub y: i64,
}

impl Point64 {
    pub const fn new(x: i64, y: i64) -> Self {
        Point64 { x, y }
    }
}

/// A sequence of points (mirrors Clipper2's `Path64`).
#[derive(Debug, Clone, Default)]
pub struct Path64 {
    points: Vec<Point64>,
}

impl Path64 {
    pub fn new() -> Self {
        Path64 { points: Vec::new() }
    }

    pub fn from_points(points: Vec<Point64>) -> Self {
        Path64 { points }
    }

    /// Number of points in the path (mirrors `Path64::size()`).
    pub fn size(&self) -> usize {
        self.points.len()
    }
}

impl FromIterator<Point64> for Path64 {
    fn from_iter<I: IntoIterator<Item = Point64>>(iter: I) -> Self {
        Path64 {
            points: iter.into_iter().collect(),
        }
    }
}

